<template><section><div class="page-header"><div><p class="eyebrow">Workspace controls</p><h1>Settings</h1><p class="lede">Keep the public booking identity and operating context clear.</p></div></div><form class="settings-grid" @submit.prevent="save"><div class="card"><h2>Business details</h2><div class="field"><label for="business">Business name</label><input id="business" v-model.trim="draft.businessName" placeholder="Not configured" maxlength="80" /></div><div class="field"><label for="timezone">Timezone</label><select id="timezone" v-model="draft.timezone"><option>UTC</option><option>America/New_York</option><option>America/Los_Angeles</option><option>Europe/London</option></select></div><button class="button button-primary" type="submit" :disabled="saving">{{ saving ? 'Saving…' : 'Save settings' }}</button><p v-if="notice" class="success" role="status">{{ notice }}</p></div><div class="card"><h2>Account & draft status</h2><div class="setting-line"><span>Goalmatic account</span><strong>{{ auth.value ? 'Authenticated' : 'Not connected' }}</strong></div><div class="setting-line"><span>Environment</span><strong class="draft-badge">Private draft</strong></div><p class="muted">This workspace is unpublished. No guest-facing changes are live.</p><button class="button" type="button" @click="toggleAuth">{{ auth.value ? 'Use preview mode' : 'Sign in with Goalmatic' }}</button></div></form></section></template>
<script setup>import { inject, reactive, ref } from 'vue'; const workspace=inject('workspace'),auth=inject('auth'),saving=ref(false),notice=ref(''),draft=reactive({businessName:workspace.businessName,timezone:workspace.timezone}); function save(){saving.value=true;setTimeout(()=>{workspace.businessName=draft.businessName;workspace.timezone=draft.timezone;saving.value=false;notice.value='Settings saved to this draft.';setTimeout(()=>notice.value='',2500)},350)} function toggleAuth(){auth.value=!auth.value}</script>
<style scoped>.settings-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:18px;max-width:900px}.card h2{margin-bottom:24px}.setting-line{display:flex;justify-content:space-between;gap:18px;padding:16px 0;border-top:1px solid var(--border);font-size:14px}.draft-badge{color:#315da8}.muted{line-height:1.55;margin:20px 0}@media(max-width:700px){.settings-grid{grid-template-columns:1fr}}</style>